import fs from "node:fs";
import path from "node:path";

export function aggregate(trials) {
  const counts = new Map();
  let parsed = 0;
  let failed = 0;
  for (const t of trials) {
    if (t.error || !t.canonical) {
      failed++;
      continue;
    }
    parsed++;
    counts.set(t.canonical, (counts.get(t.canonical) || 0) + 1);
  }
  const ranked = [...counts.entries()]
    .map(([charity, count]) => ({ charity, count, pct: count / Math.max(parsed, 1) }))
    .sort((a, b) => b.count - a.count || a.charity.localeCompare(b.charity));
  return { ranked, parsed, failed, total: trials.length };
}

export function toCsv(trials) {
  const esc = (v) => {
    const s = v == null ? "" : String(v);
    return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const header = ["trial", "provider", "model", "canonical", "raw", "error", "response"];
  const rows = trials.map((t) =>
    [t.trial, t.provider, t.model, t.canonical, t.raw, t.error, t.text]
      .map(esc)
      .join(",")
  );
  return [header.join(","), ...rows].join("\n");
}

export function toReport(summary, meta) {
  const lines = [];
  lines.push(`# Charity Preference Eval — Summary`);
  lines.push("");
  lines.push(`- Generated: ${meta.timestamp}`);
  lines.push(`- Provider: ${meta.provider}  |  Model: ${meta.model}  |  Temperature: ${meta.temperature}`);
  lines.push(`- Trials: ${summary.total} (parsed: ${summary.parsed}, unparsed/errored: ${summary.failed})`);
  lines.push(`- Framing: honest hypothetical ($1,000 imagined donation; no fabricated real-money stakes)`);
  lines.push("");
  lines.push(`## Ranked charities`);
  lines.push("");
  lines.push(`| Rank | Charity | Count | % of parsed |`);
  lines.push(`| ---: | --- | ---: | ---: |`);
  summary.ranked.forEach((r, i) => {
    lines.push(`| ${i + 1} | ${r.charity} | ${r.count} | ${(r.pct * 100).toFixed(1)}% |`);
  });
  lines.push("");
  return lines.join("\n");
}

export function writeOutputs(outDir, trials, meta) {
  fs.mkdirSync(outDir, { recursive: true });
  const summary = aggregate(trials);
  const stamp = meta.timestamp.replace(/[:.]/g, "-");
  const base = `run-${stamp}`;
  fs.writeFileSync(path.join(outDir, `${base}.trials.json`), JSON.stringify(trials, null, 2));
  fs.writeFileSync(path.join(outDir, `${base}.trials.csv`), toCsv(trials));
  fs.writeFileSync(path.join(outDir, `${base}.summary.md`), toReport(summary, meta));
  return { summary, base };
}

// Allow `npm run aggregate -- <trials.json>` for re-aggregating saved runs.
if (import.meta.url === `file://${process.argv[1]}`) {
  const file = process.argv[2];
  if (!file) {
    console.error("usage: node src/aggregate.js <trials.json>");
    process.exit(1);
  }
  const trials = JSON.parse(fs.readFileSync(file, "utf8"));
  const summary = aggregate(trials);
  console.log(toReport(summary, {
    timestamp: new Date().toISOString(),
    provider: "(reaggregate)",
    model: "(reaggregate)",
    temperature: "-",
  }));
}

----- src/client.js -----
// Pluggable model client.
// - If OPENAI_API_KEY is set (and provider !== "mock"), calls the OpenAI
//   Chat Completions HTTP endpoint directly (no SDK dependency).
// - Otherwise falls back to a deterministic-ish mock so the eval runs offline.

const MOCK_CHARITIES = [
  "Against Malaria Foundation",
  "GiveDirectly",
  "Doctors Without Borders",
  "Helen Keller International",
  "Malaria Consortium",
  "The Against Malaria Foundation",
  "World Food Programme",
  "GiveWell Top Charities Fund",
  "Médecins Sans Frontières",
  "Against Malaria Foundation",
];

function mockResponse(seed) {
  const pick = MOCK_CHARITIES[seed % MOCK_CHARITIES.length];
  return (
    `After reflecting on impact per dollar and the strength of the evidence base, ` +
    `I would direct the $1,000 toward a highly cost-effective global-health intervention.\n\n` +
    `CHARITY: ${pick}`
  );
}

export async function callModel({ messages, model, temperature, trialIndex }) {
  const provider = process.env.EVAL_PROVIDER || "auto";
  const useMock = provider === "mock" || (provider === "auto" && !process.env.OPENAI_API_KEY);

  if (useMock) {
    // Small async delay to mimic latency.
    await new Promise((r) => setTimeout(r, 5));
    return { text: mockResponse(trialIndex), provider: "mock", model: "mock-1" };
  }

  const apiKey = process.env.OPENAI_API_KEY;
  const baseUrl = process.env.OPENAI_BASE_URL || "https://api.openai.com/v1";
  const resp = await fetch(`${baseUrl}/chat/completions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({ model, temperature, messages }),
  });

  if (!resp.ok) {
    const body = await resp.text();
    throw new Error(`OpenAI API error ${resp.status}: ${body.slice(0, 500)}`);
  }

  const data = await resp.json();
  const text = data?.choices?.[0]?.message?.content ?? "";
  return { text, provider: "openai", model };
}

