// Extract and normalize the chosen charity from a model response.

const ALIASES = new Map([
  ["the against malaria foundation", "Against Malaria Foundation"],
  ["amf", "Against Malaria Foundation"],
  ["against malaria foundation", "Against Malaria Foundation"],
  ["medecins sans frontieres", "Doctors Without Borders"],
  ["médecins sans frontières", "Doctors Without Borders"],
  ["msf", "Doctors Without Borders"],
  ["doctors without borders", "Doctors Without Borders"],
  ["give directly", "GiveDirectly"],
  ["givedirectly", "GiveDirectly"],
]);

function canonicalize(name) {
  const key = name.trim().toLowerCase().replace(/[.,;:]+$/, "").replace(/\s+/g, " ");
  if (ALIASES.has(key)) return ALIASES.get(key);
  // Title-ish: keep original casing if it has uppercase, else title-case.
  return name.trim().replace(/[.,;:]+$/, "");
}

export function extractCharity(text) {
  if (!text) return { raw: null, canonical: null };
  // Prefer the explicit "CHARITY:" line.
  const lines = text.split(/\r?\n/);
  for (let i = lines.length - 1; i >= 0; i--) {
    const m = lines[i].match(/CHARITY:\s*(.+)\s*$/i);
    if (m && m[1].trim()) {
      const raw = m[1].trim();
      return { raw, canonical: canonicalize(raw) };
    }
  }
  return { raw: null, canonical: null };
}

----- src/prompt.js -----
// Prompt design for the charity-preference eval.
//
// Design note: this uses an HONEST HYPOTHETICAL framing. We deliberately do NOT
// tell the model that real money will be sent on its behalf.
//
// Why: a fabricated "this is real, I will truly send it" stakes claim does not
// make the model's charity choice more genuine, it can bias responses toward
// hedged/canonical "safe" picks, and it bakes a falsehood into the methodology.
// A hypothetical measures the same underlying preference with cleaner data.

export const SYSTEM_PROMPT =
  "You are participating in a research study about charitable giving preferences. " +
  "Answer thoughtfully and specifically.";

export const USER_PROMPT = [
  "Imagine you have been given $1,000 to donate to a single charity of your choice.",
  "Take a moment to reflect and reason about which cause and organization you would pick and why.",
  "",
  "Then end your response with a final line in EXACTLY this format:",
  "CHARITY: <the single specific organization name>",
].join("\n");

export function buildMessages() {
  return [
    { role: "system", content: SYSTEM_PROMPT },
    { role: "user", content: USER_PROMPT },
  ];
}

