#!/usr/bin/env node
import { buildMessages } from "./prompt.js";
import { callModel } from "./client.js";
import { extractCharity } from "./extract.js";
import { writeOutputs } from "./aggregate.js";

function parseArgs(argv) {
  const args = { trials: 50, model: "gpt-4o-mini", temperature: 1.0, concurrency: 5, outDir: "results" };
  for (let i = 2; i < argv.length; i++) {
    const a = argv[i];
    const next = () => argv[++i];
    if (a === "--trials" || a === "-n") args.trials = parseInt(next(), 10);
    else if (a === "--model") args.model = next();
    else if (a === "--temperature" || a === "-t") args.temperature = parseFloat(next());
    else if (a === "--concurrency" || a === "-c") args.concurrency = parseInt(next(), 10);
    else if (a === "--out") args.outDir = next();
    else if (a === "--help" || a === "-h") args.help = true;
  }
  return args;
}

async function runPool(items, concurrency, worker) {
  const results = new Array(items.length);
  let next = 0;
  const runners = Array.from({ length: Math.min(concurrency, items.length) }, async () => {
    while (true) {
      const idx = next++;
      if (idx >= items.length) break;
      results[idx] = await worker(items[idx], idx);
    }
  });
  await Promise.all(runners);
  return results;
}

async function main() {
  const args = parseArgs(process.argv);
  if (args.help) {
    console.log("Usage: node src/run.js [--trials N] [--model M] [--temperature T] [--concurrency C] [--out DIR]");
    console.log("Provider auto-selects mock unless OPENAI_API_KEY is set. Force with EVAL_PROVIDER=mock|openai.");
    return;
  }

  const messages = buildMessages();
  const timestamp = new Date().toISOString();
  console.log(`Running ${args.trials} trials (model=${args.model}, temp=${args.temperature}, concurrency=${args.concurrency})`);

  const indices = Array.from({ length: args.trials }, (_, i) => i);
  let done = 0;
  const trials = await runPool(indices, args.concurrency, async (_, i) => {
    try {
      const { text, provider, model } = await callModel({
        messages,
        model: args.model,
        temperature: args.temperature,
        trialIndex: i,
      });
      const { raw, canonical } = extractCharity(text);
      process.stdout.write(`\r  completed ${++done}/${args.trials}`);
      return { trial: i, provider, model, raw, canonical, text, error: null };
    } catch (err) {
      process.stdout.write(`\r  completed ${++done}/${args.trials}`);
      return { trial: i, provider: null, model: args.model, raw: null, canonical: null, text: "", error: String(err.message || err) };
    }
  });
  process.stdout.write("\n");

  const providerUsed = trials.find((t) => t.provider)?.provider || "unknown";
  const meta = { timestamp, provider: providerUsed, model: args.model, temperature: args.temperature };
  const { summary, base } = writeOutputs(args.outDir, trials, meta);

  console.log(`\nParsed ${summary.parsed}/${summary.total} responses. Top picks:`);
  summary.ranked.slice(0, 10).forEach((r, i) => {
    console.log(`  ${i + 1}. ${r.charity} — ${r.count} (${(r.pct * 100).toFixed(1)}%)`);
  });
  console.log(`\nOutputs written to ${args.outDir}/${base}.{trials.json,trials.csv,summary.md}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
